template <typename T>
bool ResultCmpExact(const std::vector<T>& expected, const T* actual)
{
    static_assert(std::is_integral_v<T>, "ResultCmpExact only supports integral types.");
    size_t errCount = 0;
    for (size_t i = 0; i < expected.size(); ++i) {
        if (expected[i] != actual[i]) {
